#include <bits/stdc++.h>
#include <atcoder/segtree>

using namespace std;
using namespace atcoder;

using ll = long long;

/*
  First element: Sum of C_j
  Second element: Sum of C_j \dot j
*/
using S = pair<int, ll>;

S op(const S &a, const S &b) {
    return {a.first + b.first, a.second + b.second};
}

S e() {
    return {0, 0};
}

const int C = 500010;
segtree<S, op, e> st(C);

void add(int x) {
    auto now = st.get(x);
    now.first += 1;
    now.second += x;
    st.set(x, now);
}

void del(int x) {
    auto now = st.get(x);
    now.first -= 1;
    now.second -= x;
    st.set(x, now);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int &i: a) {
        cin >> i;
        add(i);
    }
    while (q--) {
        int t;
        cin >> t;
        if (t == 1) {
            int x, y;
            cin >> x >> y;
            --x;
            del(a[x]);
            a[x] = y;
            add(a[x]);
        } else {
            int l, r;
            cin >> l >> r;
            ll ans = 0;
            if (l > r) {
                ans = (ll) l * n;
            } else {
                ans += (ll) l * st.prod(0, l).first;
                ans += st.prod(l, r + 1).second;
                ans += (ll) r * st.prod(r + 1, C).first;
            }
            cout << ans << '\n';
        }
    }
}
